# generated by gophertunnel b8bd735:
# packet.PlayStatus{Status: packet.PlayStatusPlayerSpawn}
ENCODED_PLAY_STATUS = bytes.fromhex("00000003")

PLAY_STATUS = bp.PlayStatusPacket(status=bp.PlayStatus.PLAYER_SPAWN)

PROTOCOLS = [importlib.import_module(f"bedrock_protocol.v{number}") for number in _core.modes]
FIRST_PROTOCOLS = {cls: module.__name__ for module in reversed(PROTOCOLS) for cls in _core.modes[module.VERSION]}

HEALTH = bp.AttributeData(name="health")
TRUNCATED_ATTRIBUTES = proto.encode(bp.UpdateAttributesPacket(attribute_data=[HEALTH, HEALTH]))[:-2]


def test_the_package_exports_its_functions_and_every_class_it_declares():
    declared = {name for name, value in vars(bp).items() if isinstance(value, type) and value.__module__ == bp.__name__}
    functions = {"nbt", "encode", "decode"}
    assert set(bp.__all__) == {*functions, *declared}


def test_every_type_the_latest_protocol_has_belongs_to_the_package():
    assert {cls.__module__ for cls in _core.modes[PROTOCOLS[-1].VERSION]} == {"bedrock_protocol"}


def test_a_type_the_latest_protocol_lacks_belongs_to_the_first_protocol_that_has_it(protocol):
    latest = _core.modes[PROTOCOLS[-1].VERSION].keys()
    older = [cls for cls in _core.modes[protocol.VERSION].keys() - latest if "." not in cls.__qualname__]
    assert {cls: cls.__module__ for cls in older} == {cls: FIRST_PROTOCOLS[cls] for cls in older}


def test_a_protocol_holds_only_the_types_it_introduced(protocol):
    assert {value.__module__ for value in vars(protocol).values() if isinstance(value, type)} <= {protocol.__name__}


def test_a_packet_names_the_protocol_that_introduced_it_as_its_module():
    assert v594.MovePlayerPacket.__module__ == "bedrock_protocol.v594"


@pytest.mark.parametrize(
    ("version", "name"),
    [pytest.param(v2225, "TextPacket", id="v2225"), pytest.param(v800, "LoginPacket", id="v800")],
)
def test_a_protocol_holds_no_type_the_package_declares(version, name):
    assert not hasattr(version, name)


def test_the_internal_modes_hold_every_protocol(protocol):
    assert protocol.VERSION in _core.modes


def test_the_package_has_no_pre_cereal():
    assert not hasattr(bp, "pre_cereal")


@pytest.mark.parametrize("name", ["packets", "encodings", "modes"])
def test_the_package_holds_no_protocol_tables(name):
    assert not hasattr(bp, name)


def test_the_package_leaks_nothing_at_exit():
    script = "import bedrock_protocol as bp; bp.ProtocolVersion.get(2225); bp.ProtocolVersion.SUPPORTED_VERSIONS"
    assert subprocess.run([sys.executable, "-c", script], capture_output=True, check=True, text=True).stderr == ""


def test_the_package_encodes_at_the_latest_protocol():
    assert bp.encode is PROTOCOLS[-1].encode


def test_the_package_decodes_at_the_latest_protocol():
    assert bp.decode is PROTOCOLS[-1].decode


def test_a_packet_encodes_to_the_bytes_gophertunnel_writes():
    assert proto.encode(PLAY_STATUS) == ENCODED_PLAY_STATUS


def test_a_packet_decodes_from_the_bytes_gophertunnel_writes():
    assert proto.decode(bp.PlayStatusPacket, ENCODED_PLAY_STATUS) == PLAY_STATUS


def test_a_positional_argument_is_rejected():
    with pytest.raises(TypeError, match="incompatible function arguments"):
        bp.Vec3(1, 2, 3)


def test_a_keyword_the_schema_does_not_name_is_rejected():
    with pytest.raises(TypeError, match="incompatible function arguments"):
        bp.Vec3(w=1)


@pytest.mark.parametrize(
    ("cls", "field", "value"),
    [
        pytest.param(bp.MovePlayerPacket, "teleport_data", bp.MovePlayerTeleportData(), id="optional-struct"),
        pytest.param(
            bp.CameraAimAssistCommandPresetDefinition,
            "target_mode",
            bp.TargetMode.DISTANCE,
            id="optional-enum",
        ),
        pytest.param(bp.GameRule, "value", True, id="variant-with-monostate"),
        pytest.param(v594.DataStoreChange, "new_data", 3, id="dynamic-value"),
    ],
)
def test_a_nullable_field_takes_none(cls, field, value):
    packet = cls(**{field: value})
    setattr(packet, field, None)
    assert getattr(packet, field) is None


def test_none_for_a_field_that_cannot_be_none_is_rejected():
    with pytest.raises(TypeError, match="incompatible function arguments"):
        bp.Vec3(x=None)


@pytest.mark.parametrize(
    ("cls", "field", "value", "shown"),
    [
        pytest.param(bp.ContainerClosePacket, "container_id", 1000, "1000", id="enum"),
        pytest.param(bp.ResourcePackChunkDataPacket, "resource_name", b"p", "b'p'", id="string"),
    ],
)
def test_a_setter_raises_the_constructors_message(cls, field, value, shown):
    with pytest.raises(TypeError, match=rf"^{cls.__name__}\.{field}: cannot hold {shown}$"):
        setattr(cls(), field, value)


@pytest.mark.parametrize(
    ("cls", "field", "value", "shown"),
    [
        pytest.param(bp.BiomeStringList, "strings", "abc", "'abc'", id="list-from-str"),
        pytest.param(bp.BiomeStringList, "strings", 5, "5", id="list-from-int"),
        pytest.param(bp.ActorDataBoundingBoxComponent, "value", [1.0], r"\[1\.0\]", id="array-wrong-length"),
    ],
)
def test_a_sequence_field_rejects_a_value_that_is_not_one(cls, field, value, shown):
    with pytest.raises(TypeError, match=rf"^{cls.__name__}\.{field}: cannot hold {shown}$"):
        cls(**{field: value})


def test_the_constructor_signature_is_typed_and_keyword_only():
    assert bp.Vec3.__init__.__doc__ == "__init__(self, *, x: float = ..., y: float = ..., z: float = ...) -> None"


def test_an_enum_argument_also_takes_an_int():
    assert "ContainerID | int = ..." in bp.ContainerClosePacket.__init__.__doc__


