def test_a_bytes_field_crosses_as_python_bytes():
    packet = v2168.LevelChunkPacket(serialized_chunk=bytes([0xFF, 0x00, 0xC3, 0x41]))
    assert packet.serialized_chunk == bytes([0xFF, 0x00, 0xC3, 0x41])


def test_a_bytes_field_round_trips():
    packet = v2168.LevelChunkPacket(serialized_chunk=bytes([0xFF, 0x00, 0xC3, 0x41]))
    assert proto.decode(v2168.LevelChunkPacket, proto.encode(packet)) == packet


def test_a_bytes_field_rejects_text():
    with pytest.raises(TypeError, match=r"^LevelChunkPacket\.serialized_chunk: cannot hold 'héllo'$"):
        v2168.LevelChunkPacket(serialized_chunk="héllo")


def test_a_string_field_rejects_bytes():
    with pytest.raises(TypeError, match=r"^ResourcePackChunkDataPacket\.resource_name: cannot hold b'p'$"):
        bp.ResourcePackChunkDataPacket(resource_name=b"p")


def test_a_string_carries_encoded_bytes_that_are_not_utf8():
    text = b"\xff".decode("utf-8", "surrogateescape")
    packet = bp.ResourcePackChunkDataPacket(resource_name=text)
    assert proto.decode(bp.ResourcePackChunkDataPacket, proto.encode(packet)).resource_name == text


def test_a_string_can_be_assigned_text():
    packet = bp.ResourcePackChunkDataPacket()
    packet.resource_name = "héllo"
    assert packet.resource_name == "héllo"


def test_a_uuid_crosses_as_uuid():
    value = uuid.UUID("12345678-9abc-def0-1122-334455667788")
    request = bp.CommandRequestPacket().origin
    request.uuid = value
    assert request.uuid == value
    assert _core.decode(proto.VERSION, type(request), _core.encode(proto.VERSION, request)).uuid == value


@pytest.mark.parametrize(
    "text",
    [b"6F0B5E2A-1C3D-4E8F-9A7B-2D4C6E8F0A1B", b"6f0b5e2a1c3d4e8f9a7b2d4c6e8f0a1b", b"", b"cid"],
    ids=["upper-case", "bare-digits", "empty", "not-a-uuid"],
)
def test_a_uuid_carried_as_text_keeps_its_text_as_encoded(text):
    encoded = bytes([len(text)]) + text
    assert _core.encode(proto.VERSION, _core.decode(proto.VERSION, bp.ContentIdentity, encoded)) == encoded


def test_a_python_keyword_member_keeps_the_dsl_underscore():
    assert hasattr(bp.BiomeConsolidatedFeatureData, "pass_")


def test_decode_rejects_trailing_bytes():
    with pytest.raises(bp.DecodeError, match=r"^PlayStatusPacket: trailing bytes at byte 4 of 5$"):
        proto.decode(bp.PlayStatusPacket, proto.encode(PLAY_STATUS) + b"\x00")


def test_decode_rejects_a_truncated_body():
    with pytest.raises(bp.DecodeError, match=r"^PlayStatusPacket.status: truncated at byte 0 of 3$"):
        proto.decode(bp.PlayStatusPacket, proto.encode(PLAY_STATUS)[:-1])


def test_a_decode_error_is_a_value_error():
    with pytest.raises(ValueError, match="truncated"):
        proto.decode(bp.UpdateAttributesPacket, TRUNCATED_ATTRIBUTES)


def test_a_decode_error_built_in_python_carries_its_fields():
    error = bp.DecodeError("message", "truncated", ("a", 1), 7)
    assert (str(error), error.reason, error.path, error.offset) == ("message", "truncated", ("a", 1), 7)


def test_a_decode_error_pickles_with_its_fields():
    error = pickle.loads(pickle.dumps(bp.DecodeError("message", "truncated", ("a", 1), 7)))
    assert (str(error), error.reason, error.path, error.offset) == ("message", "truncated", ("a", 1), 7)


def test_a_decode_error_carries_its_reason():
    with pytest.raises(bp.DecodeError, match="truncated") as caught:
        proto.decode(bp.UpdateAttributesPacket, TRUNCATED_ATTRIBUTES)
    assert caught.value.reason == "truncated"


def test_a_decode_error_carries_the_path_through_a_list_element():
    with pytest.raises(bp.DecodeError, match="truncated") as caught:
        proto.decode(bp.UpdateAttributesPacket, TRUNCATED_ATTRIBUTES)
    assert caught.value.path == ("attribute_data", 1, "modifiers")


def test_a_decode_error_carries_the_offset_where_the_reader_stopped():
    with pytest.raises(bp.DecodeError, match="truncated") as caught:
        proto.decode(bp.UpdateAttributesPacket, TRUNCATED_ATTRIBUTES)
    assert caught.value.offset == 65


