LATE_VERSIONS = [importlib.import_module(f"bedrock_protocol.v{number}") for number in _core.modes if number >= 2168]


def reachable_names(scope, seen):
    for name in (name for name in dir(scope) if not name.startswith("_")):
        member = getattr(scope, name)
        yield name
        if isinstance(member, type) and member not in seen:
            seen.add(member)
            yield member.__qualname__
            yield from reachable_names(member, seen)


@pytest.mark.parametrize("version", LATE_VERSIONS, ids=lambda module: module.__name__)
def test_no_cerealized_name_exists_from_2168(version):
    classes = _core.modes[version.VERSION]
    assert not any("Cerealized" in name for cls in classes for name in reachable_names(cls, set()))


